"""ASGI entrypoint with a legacy-build contract fallback."""

from __future__ import annotations

import base64
import sys
import types
import zlib


_AGENT_CONTRACTS = ""
_BROWSER_CONTRACTS = ""


def _install_compat_contracts() -> None:
    for name, payload in (
        ('asset_based_agent.agent_contracts', _AGENT_CONTRACTS),
        ('asset_based_agent.browser_contracts', _BROWSER_CONTRACTS),
    ):
        module = types.ModuleType(name)
        module.__package__ = 'asset_based_agent'
        exec(zlib.decompress(base64.b64decode(payload)), module.__dict__)
        sys.modules[name] = module


try:
    import asset_based_agent.agent_contracts  # noqa: F401
except ModuleNotFoundError:  # pragma: no cover - legacy Zeabur build context
    _install_compat_contracts()


from .api import create_app

app = create_app()
